const fs = require('fs');
const path = require('path');

// Fixed identifiers. Labels, relationship types and constraint names are
// constants, never data.
const LABEL = { COMPONENT: 'Component', STORE_KEY: 'StoreKey', ACTION: 'Action' };
const REL = { DISPATCHES: 'DISPATCHES', RENDERS: 'RENDERS', SELECTS: 'SELECTS' };
const CONSTRAINT = {
  [LABEL.COMPONENT]: 'component_name',
  [LABEL.STORE_KEY]: 'storekey_name',
  [LABEL.ACTION]: 'action_name',
};

const HEADER =
  '// Generated by react-ast-parser. Load with: cypher-shell -u <user> -p <password> -f graph.cypher';

// Code-unit comparison, so the order never depends on the locale.
const byText = (a, b) => (a < b ? -1 : a > b ? 1 : 0);

/**
 * The one escaping function. Backslash first, then the single quote, then
 * newline, carriage return and tab; every other C0 control (U+0000-U+001F)
 * and U+2028/U+2029 become \uXXXX.
 */
function escapeCypher(value) {
  return String(value)
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'")
    .replace(/\n/g, '\\n')
    .replace(/\r/g, '\\r')
    .replace(/\t/g, '\\t')
    .replace(/[\u0000-\u001f\u2028\u2029]/g, ch => '\\u' + ch.charCodeAt(0).toString(16).padStart(4, '0'));
}

const str = value => `'${escapeCypher(value)}'`;
const list = values => `[${values.map(str).join(', ')}]`;

// Path relative to the analyzed root's directory (the first component's), forward slashes.
function relativeFile(filePath, rootDir) {
  const rel = rootDir ? path.relative(rootDir, filePath) : filePath;
  return rel.split(path.sep).join('/');
}

/**
 * Turn the component data into an idempotent Cypher script.
 * Pure: the same input gives the same string.
 */
function generateCypher(data) {
  const components = (data && data.components) || [];
  const first = components.find(c => c && typeof c.filePath === 'string');
  const rootDir = first ? path.dirname(first.filePath) : null;

  const componentNodes = new Map(); // name -> { file, parseError, state }
  const storeKeys = new Set();
  const actions = new Set();
  const renders = new Map(); // "parent\0child" -> { source, target, props }
  const selects = new Map();
  const dispatches = new Map();

  // First record seen for a name wins; later same-named records only add edges.
  const ensureComponent = name => {
    if (!componentNodes.has(name)) componentNodes.set(name, { file: null, parseError: false, state: null });
    return componentNodes.get(name);
  };

  const defined = new Set();
  components.forEach(component => {
    if (!component) return;
    const name = String(component.name);
    const node = ensureComponent(name);
    if (!defined.has(name)) {
      defined.add(name);
      if (typeof component.filePath === 'string') node.file = relativeFile(component.filePath, rootDir);
      node.parseError = Boolean(component.error);
      node.state = Array.isArray(component.state) ? component.state : null;
    }

    (Array.isArray(component.children) ? component.children : []).forEach(child => {
      const childName = String(child);
      ensureComponent(childName);
      const key = `${name}\0${childName}`;
      if (!renders.has(key)) {
        const props = component.props && Array.isArray(component.props[child]) ? component.props[child] : [];
        renders.set(key, { source: name, target: childName, props });
      }
    });

    (Array.isArray(component.reduxProps) ? component.reduxProps : []).forEach(prop => {
      storeKeys.add(String(prop));
      selects.set(`${name}\0${prop}`, { source: name, target: String(prop) });
    });

    (Array.isArray(component.actions) ? component.actions : []).forEach(action => {
      actions.add(String(action));
      dispatches.set(`${name}\0${action}`, { source: name, target: String(action) });
    });
  });

  const lines = [HEADER];

  [LABEL.COMPONENT, LABEL.STORE_KEY, LABEL.ACTION].forEach(label => {
    lines.push(
      `CREATE CONSTRAINT ${CONSTRAINT[label]} IF NOT EXISTS FOR (n:${label}) REQUIRE n.name IS UNIQUE;`
    );
  });

  // Nodes: by label, then name (Action < Component < StoreKey).
  [...actions].sort(byText).forEach(name => {
    lines.push(`MERGE (n:${LABEL.ACTION} {name: ${str(name)}});`);
  });
  [...componentNodes.keys()].sort(byText).forEach(name => {
    const { file, parseError, state } = componentNodes.get(name);
    const sets = [];
    if (file !== null) sets.push(`n.file = ${str(file)}`);
    sets.push(`n.parseError = ${parseError ? 'true' : 'false'}`);
    if (state !== null) sets.push(`n.state = ${list(state)}`);
    // REMOVE clears a property the source no longer has, so a re-load of an existing node is current.
    const removes = [];
    if (file === null) removes.push('n.file');
    if (state === null) removes.push('n.state');
    const remove = removes.length ? ` REMOVE ${removes.join(', ')}` : '';
    lines.push(`MERGE (n:${LABEL.COMPONENT} {name: ${str(name)}}) SET ${sets.join(', ')}${remove};`);
  });
  [...storeKeys].sort(byText).forEach(name => {
    lines.push(`MERGE (n:${LABEL.STORE_KEY} {name: ${str(name)}});`);
  });

  // Relationships: by type, then source, then target.
  const edges = [
    [REL.DISPATCHES, LABEL.ACTION, dispatches],
    [REL.RENDERS, LABEL.COMPONENT, renders],
    [REL.SELECTS, LABEL.STORE_KEY, selects],
  ];
  edges.forEach(([type, targetLabel, map]) => {
    [...map.values()]
      .sort((a, b) => byText(a.source, b.source) || byText(a.target, b.target))
      .forEach(edge => {
        const set = type === REL.RENDERS ? ` SET r.props = ${list(edge.props)}` : '';
        lines.push(
          `MATCH (a:${LABEL.COMPONENT} {name: ${str(edge.source)}}), (b:${targetLabel} {name: ${str(edge.target)}}) ` +
            `MERGE (a)-[r:${type}]->(b)${set};`
        );
      });
  });

  return lines.join('\n') + '\n';
}

/**
 * Write the script to graph.cypher in the working directory.
 */
function writeCypher(data, quiet = false) {
  if (!data || !data.components) {
    if (!quiet) console.error('✗ No component data provided');
    return false;
  }
  const cypherFile = 'graph.cypher';
  try {
    fs.writeFileSync(cypherFile, generateCypher(data));
    if (!quiet) console.log(`✓ Generated ${cypherFile}`);
  } catch (error) {
    console.error(`✗ Failed to write ${cypherFile}: ${error.message}`);
    return false;
  }
  return true;
}

module.exports = { generateCypher, writeCypher, escapeCypher };
